window.VeilGardeData.files["Tests-VeilWatermarkTests"] = {"group":"Tests-VeilWatermarkTests","files":[{"path":"Tests/VeilWatermarkTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,51]],"header":{"lines":[1,10],"target":"VeilWatermarkTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1421,"scopes":[["E","Fixture",null,"",14,14,[14,13],51,null,-1,0,"a",[]],["f","crop",["_"],"static",22,22,[22,44],24,[21,21],0,0,"a"],["S","Fragility",null,"",27,27,[27,32],33,[26,26],0,0,"a"],["f","fragility",["_"],"static",35,35,[35,62],38,null,0,0,"a"],["S","TileDump",null,"",42,42,[42,31],45,[40,41],0,0,"a"],["f","tileDump",["_"],"static",47,47,[47,60],50,null,0,0,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the watermark tests read by repo path: the two 512-px parity crops; the fragility\n//        rate each yields at phase (0, 0) with its signature's content id, pinned on 2026-10-21\n//        before the residual moved, so the move is held to exactly the numbers it started from; and\n//        each crop's 19 tile features as the research's tile extractor dumped them.\n//\n\nimport Foundation\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    /// A parity crop (crop_ben.png, crop_fox.png).\n    static func crop(_ name: String) -> URL {\n        repoRoot.appendingPathComponent(\"Tests/VeilGardeInferenceTests/Fixtures/crops/\\(name)\")\n    }\n\n    /// The pinned fragility of one crop.\n    struct Fragility: Decodable {\n        let image: String\n        let rows: Int\n        let cols: Int\n        let cid: String\n        let fr: [Double]\n    }\n\n    static func fragility(_ name: String) throws -> Fragility {\n        let url = repoRoot.appendingPathComponent(\"Tests/VeilWatermarkTests/Fixtures/\\(name).fr.json\")\n        return try JSONDecoder().decode(Fragility.self, from: Data(contentsOf: url))\n    }\n\n    /// The research's 19 tile features of one crop, 256 tiles row-major, as its tile extractor\n    /// dumped them (restored from the 2026-rnd branch's lens parity fixtures).\n    struct TileDump: Decodable {\n        let feature_order: [String]\n        let features: [[Double]]\n    }\n\n    static func tileDump(_ name: String) throws -> TileDump {\n        let url = repoRoot.appendingPathComponent(\"Tests/VeilWatermarkTests/Fixtures/\\(name).features.json\")\n        return try JSONDecoder().decode(TileDump.self, from: Data(contentsOf: url))\n    }\n}\n"},{"path":"Tests/VeilWatermarkTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilWatermarkTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1427,"scopes":[["S","WatermarkLinkTests",null,"",12,13,[13,26],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilWatermark\n\n@Suite(\"Watermark links\")\nstruct WatermarkLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilWatermarkTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,20]],"header":{"lines":[1,9],"target":"VeilWatermarkTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1429,"scopes":[["S","WatermarkMLXSuites",null,"",19,20,[20,26],20,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under WatermarkMLXSuites, which\n//        is serialized.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Watermark: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct WatermarkMLXSuites {}\n"},{"path":"Tests/VeilWatermarkTests/ResidualTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,57]],"header":{"lines":[1,14],"target":"VeilWatermarkTests","what":[6,10],"pin":[11,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":1430,"scopes":[["S","ResidualConstantsTests",null,"",22,23,[23,30],40,null,-1,0,"a"],["f","displacements",[],"",24,25,[25,25],31,null,0,0,"a"],["f","constants",[],"",33,34,[34,21],39,null,0,0,"a"],["X","WatermarkMLXSuites",null,"",42,42,[42,29],57,null,-1,0,"a"],["S","ResidualOnGPU",null,"",43,44,[44,25],56,null,3,0,"a"],["f","fragility",["name"],"",45,46,[46,44],55,null,4,0,"a"]],"old":"","new":"//\n//  ResidualTests.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The residual the watermark reads, held still. On the CPU: the sixteen corner moves (every\n//        value, by digest) and the fixed probe's constants. On the GPU: each parity crop's fragility\n//        rate at phase (0, 0) equals, value for value, what the detector's lens measured for it before\n//        the residual moved into the watermark (column 0 of its feature dump), and its signature's\n//        content id is the one pinned that day (2026-10-21).\n//  PIN:  Exact equality, no tolerance: every signature ever written was read through this arithmetic,\n//        so a change here is a change to the watermark. The invariance run over the battery's 105\n//        images and the acceptance are the wider gates; this one runs with every test pass.\n//\n\nimport CoreGraphics\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilWatermark\n\n@Suite(\"The residual's fixed probe\")\nstruct ResidualConstantsTests {\n    @Test(\"the sixteen corner moves are the literal table, every value\")\n    func displacements() {\n        let table = WarpDisplacements.table\n        #expect(table.count == 16 && table.allSatisfy { $0.count == 4 && $0.allSatisfy { $0.count == 2 } })\n        #expect(table[0][0][0] == 0.5479120971119267 && table[15][3][1] == -0.7109516222679062)\n        let joined = table.flatMap { $0.flatMap { $0 } }.map { \"\\($0)\" }.joined(separator: \",\")\n        #expect(ContentHash.sha256Hex(Data(joined.utf8)) == \"99493153cf79bb2478dbbf8b268e167d2f9d04fd081412ec9b6eac4a705b9143\")\n    }\n\n    @Test(\"tiles of 32 px, 16 trials, a 9×9 high-pass at σ 1.5, strengths 0.025 and 0.05, 256 tiles an eval\")\n    func constants() {\n        #expect(WarpConstants.tileSize == 32 && WarpConstants.trials == 16)\n        #expect(WarpConstants.highPassKernel == 9 && WarpConstants.highPassSigma == 1.5)\n        #expect(WarpConstants.lowStrength == 0.025 && WarpConstants.highStrength == 0.05)\n        #expect(WarpConstants.evalTileBudget == 256)\n    }\n}\n\nextension WatermarkMLXSuites {\n    @Suite(\"The residual on the GPU\", .serialized)\n    struct ResidualOnGPU {\n        @Test(\"each parity crop's fragility rate and signature are the pinned ones\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func fragility(name: String) throws {\n            let pinned = try Fixture.fragility(name)\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(pinned.image))\n            let grid = try NativePlane(cg).fragility()\n            #expect(grid.rows == pinned.rows && grid.cols == pinned.cols)\n            let want = pinned.fr.map { Float($0) }\n            let worst = zip(grid.values, want).map { abs($0 - $1) }.max() ?? .infinity\n            #expect(grid.values == want, \"largest difference \\(worst)\")\n            #expect(try Watermark.sign(cg).cid == pinned.cid)\n        }\n    }\n}\n"},{"path":"Tests/VeilWatermarkTests/TileFeatureTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,66]],"header":{"lines":[1,10],"target":"VeilWatermarkTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1436,"scopes":[["X","WatermarkMLXSuites",null,"",16,16,[16,29],66,null,-1,0,"a"],["S","TileFeatureTests",null,"",17,18,[18,28],65,null,0,0,"a"],["f","dump",["name"],"",19,20,[20,39],30,null,1,0,"a"],["f","statistics",[],"",32,33,[33,33],45,null,1,0,"a"],["f","researchTiles",[],"",51,51,[51,36],64,null,1,0,"a"],["S","Image",null,"",52,52,[52,36],52,null,4,12,"a"]],"old":"","new":"//\n//  TileFeatureTests.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: warp19 as detection reads it: the 19 tile features of each parity crop equal the\n//        research's tile extractor's dump value for value; the residual statistics are each\n//        feature's mean, then its spread, over those tiles; and, when the work area's final_mixed\n//        tiles are on disk, one capped and padded image equals its research tiles.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilWatermark\n\nextension WatermarkMLXSuites {\n    @Suite(\"warp19 on the GPU\", .serialized)\n    struct TileFeatureTests {\n        @Test(\"each crop's 19 tile features equal the research's dump, value for value\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func dump(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"\\(name).png\"))\n            let plane = try TilePlane(cg)\n            #expect(plane.paddedWidth == 512 && plane.paddedHeight == 512)\n            let rows = TileFeatures.measure(plane)\n            let dump = try Fixture.tileDump(name)\n            #expect(rows.tileRows == 16 && rows.tileCols == 16 && dump.feature_order == FeatureColumn.residualFeatures)\n            let want = dump.features.flatMap { $0.map(Float.init) }\n            let worst = zip(rows.values, want).map { abs($0 - $1) }.max() ?? .infinity\n            #expect(rows.values == want, \"\\(name): max |Δ| \\(worst)\")\n        }\n\n        @Test(\"the statistics are each feature's mean, then its population spread, over the tiles\")\n        func statistics() throws {\n            let dump = try Fixture.tileDump(\"crop_fox\")\n            let rows = TileFeatureRows(tileRows: 16, tileCols: 16, values: dump.features.flatMap { $0.map(Float.init) })\n            let stats = ResidualStatistics.summarize(rows)\n            #expect(stats.count == 38 && ResidualStatistics.count == 38)\n            for k in 0..<19 {\n                let v = dump.features.map { Double(Float($0[k])) }\n                let mean = v.reduce(0, +) / Double(v.count)\n                let spread = (v.map { ($0 - mean) * ($0 - mean) }.reduce(0, +) / Double(v.count)).squareRoot()\n                #expect(abs(Double(stats[k]) - mean) <= 1e-6 * max(1, abs(mean)), \"\\(FeatureColumn.residualFeatures[k]) mean\")\n                #expect(abs(Double(stats[19 + k]) - spread) <= 1e-5 * max(1, spread), \"\\(FeatureColumn.residualFeatures[k]) spread\")\n            }\n        }\n\n        static let finalMixedTiles = URL(fileURLWithPath: \"/Volumes/T9/rao/projects/veilgarde/store/tiles/final_mixed/tiles_0000\")\n\n        @Test(\"a final_mixed image, capped and padded, equals its research tiles\",\n              .enabled(if: FileManager.default.fileExists(atPath: finalMixedTiles.path + \".images.json\")))\n        func researchTiles() throws {\n            struct Image: Decodable { let path: String; let start: Int; let rows: Int; let cols: Int }\n            let images = try JSONDecoder().decode([Image].self, from: Data(contentsOf: URL(fileURLWithPath: Self.finalMixedTiles.path + \".images.json\")))\n            let shard = try SafetensorsFile(url: URL(fileURLWithPath: Self.finalMixedTiles.path + \".tiles.safetensors\"))\n            let all = try shard.float32(\"features\")\n            for image in images.prefix(2) {\n                let url = URL(fileURLWithPath: \"/Volumes/T9/datasets/final_mixed\").appendingPathComponent(image.path)\n                let rows = TileFeatures.measure(try TilePlane(try ImageDecoding.cgImage(contentsOf: url)))\n                #expect(rows.tileRows == image.rows && rows.tileCols == image.cols)\n                let want = Array(all[(image.start * 19)..<((image.start + image.rows * image.cols) * 19)])\n                let worst = zip(rows.values, want).map { abs($0 - $1) }.max() ?? .infinity\n                #expect(worst <= 1e-4, \"\\(image.path): max |Δ| \\(worst)\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilWatermarkTests/WatermarkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,189]],"header":{"lines":[1,12],"target":"VeilWatermarkTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1442,"scopes":[["f","randomCodes",["rows","cols","seed"],"",20,20,[20,69],25,null,-1,0,"a"],["S","WatermarkTests",null,"",27,28,[28,22],106,null,-1,0,"a"],["f","codes",[],"",29,30,[30,17],45,null,1,0,"a"],["f","sections",[],"",47,48,[48,20],55,null,1,0,"a"],["f","serialization",[],"",57,58,[58,32],74,null,1,0,"a"],["f","matcher",[],"",76,77,[77,26],105,null,1,0,"a"],["f","cut",["_","r0","c0","rows","cols","flip","seed"],"",79,79,[79,128],96,null,5,4,"a"],["S","AcceptanceSampleTests",null,"",108,109,[109,29],137,null,-1,0,"a"],["f","dataset",["_"],"",110,110,[110,46],115,null,7,0,"a"],["f","finalMixed",[],"",117,118,[118,29],125,null,7,0,"a"],["f","sample",[],"",127,128,[128,18],136,null,7,0,"a"],["X","WatermarkMLXSuites",null,"",139,139,[139,29],171,null,-1,0,"a"],["S","OnGPU",null,"",140,141,[141,17],170,null,11,0,"a"],["f","signAndMatch",[],"",145,146,[146,35],158,null,12,0,"a"],["f","flattened",[],"",160,161,[161,32],169,null,12,0,"a"],["S","WatermarkInvarianceTests",null,"",173,174,[174,32],189,null,-1,0,"a"],["f","row",["_","cid","bits"],"static",175,175,[175,90],178,null,15,0,"a"],["f","compare",[],"",180,181,[181,19],188,null,15,0,"a"]],"old":"","new":"//\n//  WatermarkTests.swift\n//  VeilWatermarkTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: VeilWatermark v1's mechanics: tile codes and their edge masks, section packing, every\n//        serialization (binary, vw1 text, JSON, the content id), and the matcher on synthetic\n//        grids; then, on the GPU, that signing is deterministic, that an image matches itself\n//        at offset 0 with score 1, and that a tile-aligned crop matches at its exact offset.\n//        Whether v1 survives real crops and re-encodes is the acceptance run's question\n//        (`veilgarde watermark accept`), not these tests'.\n//\n\nimport CoreGraphics\nimport Foundation\nimport Testing\nimport VeilGardeCore\n@testable import VeilWatermark\n\nfunc randomCodes(rows: Int, cols: Int, seed: UInt64) -> TileCodeGrid {\n    var rng = SplitMix64(seed: seed)\n    var values = [Float](repeating: 0, count: rows * cols)\n    for i in values.indices { values[i] = Float(rng.unit()) }\n    return TileCodeGrid(FragilityGrid(rows: rows, cols: cols, values: values))\n}\n\n@Suite(\"Watermark mechanics\")\nstruct WatermarkTests {\n    @Test(\"tile codes: four ordinal bits against E, S, SE, NE, masked at the edges\")\n    func codes() {\n        // 2 × 3:  1 5 2\n        //         4 3 6\n        let g = TileCodeGrid(FragilityGrid(rows: 2, cols: 3, values: [1, 5, 2, 4, 3, 6]))\n        // Tile (0,0)=1: E 5 no, S 4 no, SE 3 no, NE outside.\n        #expect(g.bits[0] == 0 && g.masks[0] == 0b0111)\n        // Tile (0,1)=5: E 2 yes, S 3 yes, SE 6 no, NE outside.\n        #expect(g.bits[1] == 0b0011 && g.masks[1] == 0b0111)\n        // Tile (0,2)=2: only S (6) is inside: no.\n        #expect(g.bits[2] == 0 && g.masks[2] == 0b0010)\n        // Tile (1,0)=4: E 3 yes, S and SE outside, NE 5 no.\n        #expect(g.bits[3] == 0b0001 && g.masks[3] == 0b1001)\n        // Tile (1,2)=6: nothing forward is inside.\n        #expect(g.masks[5] == 0)\n        #expect(g.measuredBits == 3 + 3 + 1 + 2 + 2 + 0)\n    }\n\n    @Test(\"sections pack sixteen nibbles a word and unpack exactly, borders masked\")\n    func sections() {\n        for (r, c) in [(1, 1), (4, 4), (7, 9), (13, 5)] {\n            let g = randomCodes(rows: r, cols: c, seed: UInt64(r * 100 + c))\n            let (codes, masks) = Sectioning.pack(g)\n            #expect(codes.count == Sectioning.sectionRows(r) * Sectioning.sectionCols(c))\n            #expect(Sectioning.unpack(codes: codes, masks: masks, rows: r, cols: c) == g)\n        }\n    }\n\n    @Test(\"a signature round-trips through binary, vw1 text and JSON, and its cid is its bytes'\")\n    func serialization() throws {\n        let sig = WatermarkSignature(grid: randomCodes(rows: 11, cols: 17, seed: 9))\n        #expect(try WatermarkSignature(binary: sig.binary) == sig)\n        #expect(sig.compact.hasPrefix(\"vw1:\") && !sig.compact.contains(\"=\") && !sig.compact.contains(\"+\"))\n        #expect(try WatermarkSignature(compact: sig.compact) == sig)\n        let json = try JSONCoding.prettyEncoder().encode(sig)\n        #expect(try JSONDecoder().decode(WatermarkSignature.self, from: json) == sig)\n        #expect(sig.cid == ContentHash.sha256Hex(sig.binary) && sig.cid.count == 64)\n        #expect(sig.tileCodes == randomCodes(rows: 11, cols: 17, seed: 9))\n        var tampered = try JSONSerialization.jsonObject(with: json) as! [String: Any]\n        var words = tampered[\"codes\"] as! [String]\n        words[0] = String(format: \"%016llx\", (UInt64(words[0], radix: 16)! ^ 1))\n        tampered[\"codes\"] = words\n        #expect(throws: VeilGardeFailure.self) { try JSONDecoder().decode(WatermarkSignature.self, from: try JSONSerialization.data(withJSONObject: tampered)) }\n        #expect(throws: VeilGardeFailure.self) { try WatermarkSignature(binary: Data(\"VW2\\0\".utf8) + sig.binary.dropFirst(4)) }\n        #expect(throws: VeilGardeFailure.self) { try WatermarkSignature(binary: sig.binary.dropLast(8)) }\n    }\n\n    @Test(\"the matcher finds a sub-grid's offset, tolerates flipped bits, and scores a stranger at chance\")\n    func matcher() throws {\n        let stored = randomCodes(rows: 24, cols: 30, seed: 1)\n        func cut(_ g: TileCodeGrid, r0: Int, c0: Int, rows: Int, cols: Int, flip: Double = 0, seed: UInt64 = 0) -> TileCodeGrid {\n            var rng = SplitMix64(seed: seed)\n            var bits: [UInt8] = [], masks: [UInt8] = []\n            for r in r0..<(r0 + rows) {\n                for c in c0..<(c0 + cols) {\n                    var b = g.bits[r * g.cols + c]\n                    for k in 0..<4 where rng.unit() < flip { b ^= 1 << k }\n                    bits.append(b)\n                    // The crop's own edge: its last row and column cannot compare forward.\n                    var m = g.masks[r * g.cols + c]\n                    if r == r0 + rows - 1 { m &= ~(0b0110) }\n                    if c == c0 + cols - 1 { m &= ~(0b1101) }\n                    if r == r0 { m &= ~(0b1000) }\n                    masks.append(m)\n                }\n            }\n            return TileCodeGrid(rows: rows, cols: cols, bits: bits, masks: masks)\n        }\n        let exact = try #require(Matcher.best(crop: cut(stored, r0: 5, c0: 7, rows: 12, cols: 14), stored: stored, minimumBits: 256))\n        #expect(exact.dx == 7 && exact.dy == 5 && exact.score == 1)\n        let noisy = try #require(Matcher.best(crop: cut(stored, r0: 9, c0: 3, rows: 12, cols: 14, flip: 0.1, seed: 4), stored: stored, minimumBits: 256))\n        #expect(noisy.dx == 3 && noisy.dy == 9 && abs(noisy.score - 0.9) < 0.05)\n        let stranger = try #require(Matcher.best(crop: randomCodes(rows: 12, cols: 14, seed: 77), stored: stored, minimumBits: 256))\n        #expect(stranger.score < 0.62, \"the best of many chance alignments stays near 0.5: \\(stranger.score)\")\n        #expect(Matcher.best(crop: randomCodes(rows: 3, cols: 3, seed: 5), stored: stored, minimumBits: 256) == nil, \"too few bits to judge\")\n        #expect(abs(Matcher.zScore(score: 0.75, bits: 400) - 10) < 1e-9)\n    }\n}\n\n@Suite(\"The acceptance's sample\")\nstruct AcceptanceSampleTests {\n    func dataset(_ csv: String) throws -> URL {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-fm-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        try csv.write(to: dir.appendingPathComponent(\"manifest.csv\"), atomically: true, encoding: .utf8)\n        return dir\n    }\n\n    @Test(\"final_mixed's CSV reads in file order, quotes and all\")\n    func finalMixed() throws {\n        let dir = try dataset(\"dest_name,class,source_pool,tag,scored_verdict,src_path\\r\\niphone_real_00000.jpeg,real,iphone,iphone,real,\\\"/a,b/IMG.jpeg\\\"\\r\\nagvr_ai_00001.png,generated,agvr_gen,fill,generated,/x.png\\r\\n\")\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let items = try AcceptanceSample.dataset(dir)\n        #expect(items.map(\\.url.lastPathComponent) == [\"iphone_real_00000.jpeg\", \"agvr_ai_00001.png\"])\n        #expect(items.map { $0.url.deletingLastPathComponent().lastPathComponent } == [\"real\", \"generated\"])\n        #expect(items.map(\\.label) == [0, 1])\n    }\n\n    @Test(\"the sample is seeded, at most n of each label, in the dataset's order\")\n    func sample() {\n        let items = (0..<200).map { AcceptanceSample.Item(url: URL(fileURLWithPath: \"/d/\\($0).jpg\"), label: $0 % 3 == 0 ? 1 : 0) }\n        let a = AcceptanceSample.sample(items, perLabel: 10, seed: 0)\n        #expect(a.count == 20 && a.filter { $0.label == 1 }.count == 10)\n        #expect(a == AcceptanceSample.sample(items, perLabel: 10, seed: 0))\n        #expect(a != AcceptanceSample.sample(items, perLabel: 10, seed: 1))\n        let order = a.map { Int($0.url.deletingPathExtension().lastPathComponent)! }\n        #expect(order == order.sorted(), \"kept rows stay in the dataset's order\")\n    }\n}\n\nextension WatermarkMLXSuites {\n    @Suite(\"Watermark on the GPU\", .serialized)\n    struct OnGPU {\n        static let image = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()\n            .appendingPathComponent(\"VeilGardeInferenceTests/Fixtures/crops/crop_ben.png\")\n\n        @Test(\"signing is deterministic, an image matches itself, a tile-aligned crop matches at its offset\")\n        func signAndMatch() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Self.image)\n            let a = try Watermark.sign(cg), b = try Watermark.sign(cg)\n            #expect(a == b && a.cid == b.cid)\n            #expect(a.rows == 16 && a.cols == 16)\n            let me = try Watermark.match(cg, against: a, options: MatchOptions(phases: [0]))\n            #expect(me.matched && me.score == 1 && me.offsetX == 0 && me.offsetY == 0)\n            let crop = try #require(ImageLoading.renderCrop(cg, CGRect(x: 96, y: 160, width: 320, height: 288)))\n            let r = try Watermark.match(crop, against: a, options: MatchOptions(phases: [0]))\n            #expect(r.matched && r.score == 1 && r.offsetX == 3 && r.offsetY == 5 && r.pixelX == 96 && r.pixelY == 160)\n            let full = try Watermark.match(crop, against: a)\n            #expect(full.score == 1 && full.phaseX == 0 && full.phaseY == 0, \"the full phase search finds the aligned phase\")\n        }\n\n        @Test(\"flattening to the lens's 8-bit bitmap leaves the signature unchanged; a JPEG of it still matches\")\n        func flattened() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Self.image)\n            let flat = try #require(ImageCodec.flattened(cg))\n            #expect(ImageCodec.isFlat(flat))\n            #expect(try Watermark.sign(flat) == Watermark.sign(cg))\n            let jpeg = try ImageCodec.recompressed(flat, as: .jpeg, quality: 0.75)\n            let r = try Watermark.match(jpeg, against: try Watermark.sign(cg), options: MatchOptions(phases: [0]))\n            #expect(r.offsetX == 0 && r.offsetY == 0 && r.score > 0.75, \"JPEG 0.75 scored \\(r.score)\")\n        }\n    }\n}\n\n@Suite(\"Watermark invariance\")\nstruct WatermarkInvarianceTests {\n    static func row(_ path: String, cid: String = \"c1\", bits: Int = 930) -> InvarianceRow {\n        InvarianceRow(path: path, fileSHA256: \"f-\\(path)\", width: 512, height: 512, rows: 16, cols: 16, sections: 16, measuredBits: bits, cid: cid,\n                      compactSHA256: \"k-\\(cid)\", seconds: 1)\n    }\n\n    @Test(\"equal reports have no difference; a moved signature, a lost image and a new one each show\")\n    func compare() {\n        let baseline = InvarianceReport(date: Date(), coreVersion: \"x\", images: [Self.row(\"/a.png\"), Self.row(\"/b.png\")], skipped: [])\n        #expect(WatermarkInvariance.compare(baseline: baseline, current: baseline).isEmpty)\n        let moved = InvarianceReport(date: Date(), coreVersion: \"x\", images: [Self.row(\"/a.png\", cid: \"c2\", bits: 929), Self.row(\"/c.png\")], skipped: [\"/b.png: gone\"])\n        let d = WatermarkInvariance.compare(baseline: baseline, current: moved)\n        #expect(Set(d.map(\\.field)) == [\"cid\", \"compactSHA256\", \"measuredBits\", \"signed\"])\n        #expect(d.contains { $0.path == \"/b.png\" && $0.current == \"no\" } && d.contains { $0.path == \"/c.png\" && $0.baseline == \"absent\" })\n    }\n}\n"}]};
